Q: Can we do Easing.BezierSpline animation when initial and final values are equal or almost equal? A: <p>I reworked your exercise so that:</p>
<ol>
<li>control_points still exist but now uses normalized coordinates 0.0 - 1.0</li>
<li>I added a t property which is normalized and animates from 0.0 to 1.0</li>
<li>I use Qt6.4's <code>list&lt;var&gt;</code> to simplify the model syntax</li>
<li>I refactored a TrailView component that houses the animation</li>
<li>I implemented a cubic curve formula interpolating the control_points and t</li>
</ol>
<pre class="lang-none prettyprint-override"><code>import QtQuick
import QtQuick.Controls

Page {
    background: Rectangle { color: &quot;black&quot; }

    component TrailView : Item {
        id: trailView
        anchors.fill: parent
        anchors.margins: 25
        property list&lt;var&gt; control_points
        property list&lt;var&gt; trailData: []
        property real t: 0
        property color color: Qt.lighter(&quot;green&quot;)
        onTChanged: {
            const [[x0,y0],[x1,y1],[x2,y2],[x3,y3]] = control_points;
            const u = 1 - t;
            const b0 = u * u * u;
            const b1 = 3 * u * u * t;
            const b2 = 3 * u * t * t;
            const b3 = t * t * t;
            const x = b0*x0 + b1*x1 + b2*x2 + b3*x3;
            const y = b0*y0 + b1*y1 + b2*y2 + b3*y3;
            trailData.push([x, y]);
            trailHead.cx = x;
            trailHead.cy = y;
        }
        Repeater {
            model: trailData
            delegate: Rectangle {
                x: modelData[0] * trailView.width - 1
                y: modelData[1] * trailView.height - 1
                width: 2
                height: 2
                color: trailView.color
            }
        }
        Rectangle {
            id: trailHead
            property real cx: 0
            property real cy: 0
            x: cx * trailView.width - 25
            y: cy * trailView.height - 25
            width: 50
            height: 50
            color: trailView.color
        }
        NumberAnimation on t { duration: 2000; to: 1 }
    }

    TrailView {
        color: Qt.lighter(&quot;red&quot;)
        control_points: [ [0,1/2], [1/3,0], [2/3,0], [1,0] ]
    }

    TrailView {
        color: Qt.lighter(&quot;yellow&quot;)
        control_points: [ [0,1/2], [1/3,0], [2/3,0], [1,1/4] ]
    }

    TrailView {
        color: Qt.lighter(&quot;green&quot;)
        control_points: [ [0,1/2], [1/3,0], [2/3,0], [1,1/2] ]
    }


    TrailView {
        color: Qt.lighter(&quot;cyan&quot;)
        control_points: [ [0,1/2], [1/3,0], [2/3,0], [1,3/4] ]
    }


    TrailView {
        color: Qt.lighter(&quot;blue&quot;)
        control_points: [ [0,1/2], [1/3,0], [2/3,0], [1,1] ]
    }
}
</code></pre>
